17	// IsAccessibleMode returns true if accessibility mode should be enabled.
18	// This checks the ACCESSIBLE environment variable.
19	// Set ACCESSIBLE=1 (or any non-empty value) to enable accessible mode,
20	// which uses simpler prompts that work better with screen readers.
21	func IsAccessibleMode() bool {
22		return os.Getenv("ACCESSIBLE") != ""
23	}
