30	// NewAccessibleForm creates a new huh form with accessibility mode
31	// enabled if the ACCESSIBLE environment variable is set.
32	// Note: WithAccessible() is only available on forms, not individual fields.
33	// Always wrap confirmations and other prompts in a form to enable accessibility.
34	func NewAccessibleForm(groups ...*huh.Group) *huh.Form {
35		form := huh.NewForm(groups...).WithTheme(entireTheme())
36		if IsAccessibleMode() {
37			form = form.WithAccessible(true)
38		}
39		return form
40	}
