42	// handleFormCancellation handles cancellation from huh form prompts.
43	// User abort (Ctrl+C) and timeout both print a cancelled message and return nil.
44	// Other errors are wrapped with the action name for context.
45	func handleFormCancellation(w io.Writer, action string, err error) error {
46		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
47			fmt.Fprintf(w, "%s cancelled.\n", action)
48			return nil
49		}
50		return fmt.Errorf("%s prompt failed: %w", action, err)
51	}
